export default function select({ events, previous, allowed }) {
  const list = allowed
    .split(",")
    .map((x) => x.trim().toLowerCase())
    .filter(Boolean);
  if (!list.length || list.includes("update me")) throw Error("Configure allowed senders");
  const filtered = events.filter((e) => {
    const m = e.sender.match(/<([^<>]+)>/);
    return list.includes("*") || list.includes((m?.[1] ?? e.sender).trim().toLowerCase());
  });
  const index = (previous?.index ?? -1) + 1;
  return {
    state: { index },
    more: index < filtered.length,
    id: filtered[index]?.messageId ?? "unused",
    threadId: filtered[index]?.threadId ?? "unused",
  };
}

