export default function clean({ body }) {
  if (typeof body !== "string" || !body.trim()) throw Error("Email body is empty");
  const text = body.split(/\r?\n/),
    out = [];
  for (const line of text) {
    if (
      /^On .+wrote:\s*$/i.test(line.trim()) ||
      /^\s*>/.test(line) ||
      /^[- ]{2,}Original Message[- ]*$/i.test(line.trim())
    )
      break;
    out.push(line);
  }
  const reply = out.join("\n").trim();
  if (!reply) throw Error("No unquoted message text");
  if (reply.length > 14800) throw Error("Message exceeds source input limit");
  return { body: reply };
}

