import { randomUUID } from "node:crypto";
export default async function reserve(
  { id, threadId, body, draft, feedbackUrl, acknowledge, resolution },
  ctx,
) {
  const key = "email-feedback:" + id;
  let s = await ctx.state.get(key);
  if (!s) {
    const u = new URL(feedbackUrl);
    if (u.protocol !== "https:") throw Error("Configure HTTPS feedback URL");
    s = { id, threadId, body, draft, token: randomUUID(), phase: "sheet" };
    await ctx.state.set(key, s);
  }
  if (s.pending) {
    if (acknowledge !== key + ":" + s.pending || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending " + key + ":" + s.pending);
    if (resolution === "confirmed") s.phase = s.pending === "sheet" ? "reply" : "done";
    s.pending = null;
    await ctx.state.set(key, s);
  }
  const phase = s.phase;
  if (phase !== "done") {
    s.pending = phase;
    await ctx.state.set(key, s);
  }
  const u = new URL(feedbackUrl);
  u.searchParams.set("id", s.token);
  const yes = new URL(u);
  yes.searchParams.set("feedback", "Yes");
  const no = new URL(u);
  no.searchParams.set("feedback", "No");
  return {
    phase,
    key,
    token: s.token,
    values: [[s.token, s.body, s.draft, ""]],
    reply: s.draft + "\n\nWas this message helpful?\nYes: " + yes + "\nNo: " + no,
    threadId: s.threadId,
    messageId: s.id,
  };
}

