export default async function confirm({ key, phase, ok }, ctx) {
  if (!ok) throw Error("Write outcome unknown");
  const s = await ctx.state.get(key);
  if (!s || s.pending !== phase) throw Error("Missing pending write");
  s.pending = null;
  s.phase = phase === "sheet" ? "reply" : "done";
  await ctx.state.set(key, s);
  return { ok: true };
}

