export default function row({ query, values, sheet }) {
  const id = query.id,
    feedback = query.feedback;
  if (typeof id !== "string" || !/^[-0-9a-f]{36}$/i.test(id) || !["Yes", "No"].includes(feedback))
    throw Error("Invalid feedback");
  if (!/^[A-Za-z0-9_ -]+$/.test(sheet)) throw Error("Invalid sheet name");
  const matches = values.map((x, i) => ({ x, i })).filter((o) => o.x[0] === id);
  if (matches.length !== 1) throw Error("Feedback ID not found or ambiguous");
  return { range: "'" + sheet + "'!D" + (matches[0].i + 1), values: [[feedback]] };
}
